cd /home/exedev/shipshape-shakedown/.eval-scratch/todomvc-mm/sim && node -e "
const w = require('./watchbill.json');
const fs = require('fs');
const all = [];
for (const v of Object.values(w)) all.push(...v.scenarios);
const unique = new Set(all);
console.log('total scenarios:', all.length, 'unique:', unique.size);
let missing = 0;
for (const ref of unique) {
  const [file, name] = ref.split(':');
  if (!fs.existsSync(file)) { console.log('MISSING FILE:', ref); missing++; continue; }
  const text = fs.readFileSync(file, 'utf8');
  if (!text.includes('Scenario: ' + name) && !text.includes('Scenario Outline: ' + name)) { console.log('MISSING SCENARIO:', ref); missing++; }
}
console.log('missing references:', missing);
"

